[Expected Approach] Using Stack - O(n) Time and O(n) SpaceThe idea is to traverse the array and use a stack to store elements. For each element, resolve collisions with the stack top whenever they have opposite signs, by removing the smaller absolute value or both if equal. Continue this process until no conflict remains, then push the current element. The stack finally contains the valid elements after handling all adjacent opposite sign interactions.
            C++

    #include <iostream>
#include <vector>
using namespace std;

vector<int> reducePairs(vector<int>& arr) {

    vector<int> s;

    // Traverse each element
    for (int element : arr) {

        // Process while there is a collision (opposite signs)
        while (!s.empty() && s.back() * element < 0) {

            int top = s.back();

            // Top has larger absolute value, keep top
            if (abs(top) > abs(element)) {
                element = top;
                s.pop_back();
            }

            // Current element has larger absolute value
            // keep current element
            else if (abs(top) < abs(element)) {
                s.pop_back();  
            }

            // Both have same absolute value, both removed
            else {
                s.pop_back(); 
                element = 0; 
                break;
            }
        }

        // If current element still exists, push into stack
        if (element != 0)
            s.push_back(element);
    }

    return s;
}

int main() {
    vector<int> arr = {10, -5, -8, 2, -5};  

    vector<int> result = reducePairs(arr);  

    for (int i = 0; i < result.size(); i++) {
        cout << result[i] << " ";
    }

    return 0;
}


